import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine } from '../src/invoices.js';

test('createInvoice creates a valid invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-06-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  });

  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
  assert.equal(r.value.issueDate, '2025-06-15');
  assert.equal(r.value.status, 'draft');
  assert.equal(r.value.lines.length, 2);

  assert.equal(r.value.lines[0].sku, 'DES-HOUR');
  assert.equal(r.value.lines[0].name, 'Design work (hour)');
  assert.equal(r.value.lines[0].qty, 10);
  assert.equal(r.value.lines[0].unitPrice, 8500);
  assert.equal(r.value.lines[0].vatRate, 21);

  assert.equal(r.value.lines[1].sku, 'DEV-HOUR');
  assert.equal(r.value.lines[1].name, 'Development (hour)');
  assert.equal(r.value.lines[1].qty, 5);
  assert.equal(r.value.lines[1].unitPrice, 9500);
  assert.equal(r.value.lines[1].vatRate, 21);
});

test('createInvoice reports an unknown customer', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-999',
      issueDate: '2025-06-15',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'CUSTOMER_NOT_FOUND' }
  );
});

test('createInvoice reports an invalid issue date format', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2025/06/15',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice reports an invalid month', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2025-13-01',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice reports an invalid day', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2025-02-30',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice reports an invalid date string', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: 'not-a-date',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice reports empty lines', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2025-06-15',
      lines: [],
    }),
    { ok: false, error: 'NO_LINES' }
  );
});

test('createInvoice reports non-array lines', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2025-06-15',
      lines: null,
    }),
    { ok: false, error: 'NO_LINES' }
  );
});

test('createInvoice reports invalid quantity (zero)', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2025-06-15',
      lines: [{ sku: 'DES-HOUR', qty: 0 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice reports invalid quantity (negative)', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2025-06-15',
      lines: [{ sku: 'DES-HOUR', qty: -5 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice reports invalid quantity (decimal)', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2025-06-15',
      lines: [{ sku: 'DES-HOUR', qty: 2.5 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice reports an unknown SKU', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2025-06-15',
      lines: [{ sku: 'UNKNOWN-SKU', qty: 1 }],
    }),
    { ok: false, error: 'UNKNOWN_SKU' }
  );
});

test('createInvoice does not mutate input', () => {
  const lines = [{ sku: 'DES-HOUR', qty: 1 }];
  const original = JSON.parse(JSON.stringify(lines));

  createInvoice({
    customerId: 'C-001',
    issueDate: '2025-06-15',
    lines,
  });

  assert.deepEqual(lines, original);
});

test('createInvoice handles different VAT rates', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-06-15',
    lines: [
      { sku: 'PRINT-A4', qty: 100 },
      { sku: 'WORKSHOP-DAY', qty: 1 },
    ],
  });

  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].vatRate, 9);
  assert.equal(r.value.lines[1].vatRate, 0);
});

test('lineTotal calculates qty times unitPrice', () => {
  assert.equal(lineTotal({ qty: 10, unitPrice: 8500 }), 85000);
  assert.equal(lineTotal({ qty: 1, unitPrice: 120000 }), 120000);
  assert.equal(lineTotal({ qty: 100, unitPrice: 37 }), 3700);
});

test('lineTotal returns zero for zero quantity', () => {
  assert.equal(lineTotal({ qty: 0, unitPrice: 8500 }), 0);
});

test('invoiceTotals sums line totals and equals subtotal', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-06-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  }).value;

  const totals = invoiceTotals(invoice);

  const expectedSubtotal = 10 * 8500 + 5 * 9500;
  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.total, expectedSubtotal);
});

test('invoiceTotals handles single line', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-06-15',
    lines: [
      { sku: 'LOGO-PACK', qty: 3 },
    ],
  }).value;

  const totals = invoiceTotals(invoice);

  assert.equal(totals.subtotal, 360000);
  assert.equal(totals.total, 360000);
});

test('invoiceTotals works with mixed prices', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-06-15',
    lines: [
      { sku: 'STICKER', qty: 1000 },
      { sku: 'ICON-SET', qty: 5 },
      { sku: 'BRAND-BOOK', qty: 1 },
    ],
  }).value;

  const totals = invoiceTotals(invoice);

  const expectedSubtotal = 1000 * 50 + 5 * 980 + 1 * 245000;
  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.total, expectedSubtotal);
});

test('addLine adds a new line at the end', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-06-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  }).value;

  const r = addLine(invoice, { sku: 'DEV-HOUR', qty: 5 });

  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 2);
  assert.equal(r.value.lines[1].sku, 'DEV-HOUR');
  assert.equal(r.value.lines[1].qty, 5);
  assert.equal(r.value.lines[1].name, 'Development (hour)');
  assert.equal(r.value.lines[1].unitPrice, 9500);
});

test('addLine increases qty for existing SKU', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-06-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  }).value;

  const r = addLine(invoice, { sku: 'DES-HOUR', qty: 5 });

  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 1);
  assert.equal(r.value.lines[0].sku, 'DES-HOUR');
  assert.equal(r.value.lines[0].qty, 15);
});

test('addLine reports NOT_DRAFT for non-draft invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-06-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  }).value;
  invoice.status = 'sent';

  assert.deepEqual(addLine(invoice, { sku: 'DEV-HOUR', qty: 5 }), {
    ok: false,
    error: 'NOT_DRAFT',
  });
});

test('addLine reports QTY_INVALID', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-06-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  }).value;

  assert.deepEqual(addLine(invoice, { sku: 'DEV-HOUR', qty: 0 }), {
    ok: false,
    error: 'QTY_INVALID',
  });

  assert.deepEqual(addLine(invoice, { sku: 'DEV-HOUR', qty: -5 }), {
    ok: false,
    error: 'QTY_INVALID',
  });

  assert.deepEqual(addLine(invoice, { sku: 'DEV-HOUR', qty: 2.5 }), {
    ok: false,
    error: 'QTY_INVALID',
  });
});

test('addLine reports UNKNOWN_SKU', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-06-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  }).value;

  assert.deepEqual(addLine(invoice, { sku: 'UNKNOWN', qty: 5 }), {
    ok: false,
    error: 'UNKNOWN_SKU',
  });
});

test('addLine does not mutate original invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-06-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  }).value;

  const original = JSON.parse(JSON.stringify(invoice));

  addLine(invoice, { sku: 'DEV-HOUR', qty: 5 });

  assert.deepEqual(invoice, original);
});

test('removeLine removes a line by SKU', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-06-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'COPY-HOUR', qty: 3 },
    ],
  }).value;

  const r = removeLine(invoice, 'DEV-HOUR');

  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 2);
  assert.equal(r.value.lines[0].sku, 'DES-HOUR');
  assert.equal(r.value.lines[1].sku, 'COPY-HOUR');
});

test('removeLine reports NOT_DRAFT for non-draft invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-06-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  }).value;
  invoice.status = 'paid';

  assert.deepEqual(removeLine(invoice, 'DES-HOUR'), {
    ok: false,
    error: 'NOT_DRAFT',
  });
});

test('removeLine reports LINE_NOT_FOUND', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-06-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  }).value;

  assert.deepEqual(removeLine(invoice, 'UNKNOWN'), {
    ok: false,
    error: 'LINE_NOT_FOUND',
