test('lineTotal calculates qty times unitPrice', () => {
  assert.equal(lineTotal({ qty: 10, unitPrice: 8500 }), 85000);
  assert.equal(lineTotal({ qty: 1, unitPrice: 120000 }), 120000);
  assert.equal(lineTotal({ qty: 100, unitPrice: 37 }), 3700);
});

test('lineTotal returns zero for zero quantity', () => {
  assert.equal(lineTotal({ qty: 0, unitPrice: 8500 }), 0);
});

test('invoiceTotals sums line totals and equals subtotal', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-06-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  }).value;

  const totals = invoiceTotals(invoice);

  const expectedSubtotal = 10 * 8500 + 5 * 9500;
  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.total, expectedSubtotal);
});

test('invoiceTotals handles single line', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-06-15',
